414	void LiaStarExtension::eagerCheckStar(Node literal, Node lambda)
415	{
416	  // Eager reduction: compute every cone of p up front and emit the exact
417	  // equivalence `literal = star`. Each literal is reduced at most once.
418	  if (std::find(
419	          d_processedStarTerms.begin(), d_processedStarTerms.end(), literal)
420	      != d_processedStarTerms.end())
421	  {
422	    return;
423	  }
424	  // Normalize p to DNF and render each disjunct as a Normaliz constraint matrix.
425	  std::vector<std::pair<std::vector<std::string>, Node>> pairs =
426	      convertQFLIAToMatrices(lambda);
427	
428	  // Build the cones and the star constraints over all of them.
429	  auto [cones, starConstraints] = getCones(literal, pairs);
430	
431	  if (TraceIsOn("liastar-ext-smt"))
432	  {
433	    // Debug only: build the per-cone membership encoding (v in S, a single
434	    // element) and emit (check-sat) queries asserting it is equivalent to the
435	    // predicate, so a separate solver run can validate the cone decomposition.
436	    // The actual lemma below uses `starConstraints`, not `lia`.
437	    std::vector<std::pair<Node, Node>> lia =
438	        getMembershipDisjuncts(lambda, cones);
439	    Trace("liastar-ext") << "lia constraint: " << std::endl;
440	    traceMembershipValidation(d_nm, lambda, lia);
441	  }
442	  Node star = d_nm->mkNode(Kind::AND, starConstraints);
443	  Trace("liastar-ext") << "starConstraints: " << std::endl
444	                       << toString(starConstraints) << std::endl;
445	  star = rewrite(star);
446	  Node lemma = literal.eqNode(star);
447	  Trace("liastar-ext") << "star lemma: " << lemma << std::endl;
448	  if (d_proofGen != nullptr)
449	  {
450	    d_proofGen->registerContainsReduce(lemma, literal, star);
451	  }
452	  d_im.addPendingLemma(
453	      lemma, InferenceId::ARITH_LIA_STAR_EXISTS, d_proofGen.get());
454	  d_processedStarTerms.push_back(literal);
455	  d_im.doPendingLemmas();
456	}
