512	void LiaStarExtension::lazyCheckStar(Node literal, Node lambda)
513	{
514	  // Lazy reduction: drive one refinement round for `literal`. Stop refining
515	  // once the literal has been fully reduced (its term marked processed).
516	  if (std::find(
517	          d_processedStarTerms.begin(), d_processedStarTerms.end(), literal)
518	      != d_processedStarTerms.end())
519	  {
520	    return;
521	  }
522	
523	  // The persistent incremental subsolver for this lambda. On first use it is
524	  // seeded with the (nonnegative) predicate.
525	  Subsolver& sub = getSubsolver(lambda);
526	
527	  // Refine the subsolver with the cone-disjuncts discovered since the previous
528	  // round. The refined formula -- the negated union of every disjunct found so
529	  // far -- subsumes the previous round's, so instead of accumulating one
530	  // assertion per disjunct we pop the previous refined formula and assert the
531	  // new one in a fresh frame: the subsolver always holds just the base
532	  // predicate (at the base user level) plus a single refined formula. The
533	  // disjuncts are stored in bound-variable space, so map them to skolem space
534	  // first.
535	  std::vector<std::pair<Node, libnormaliz::Cone<Integer>>>& pairs =
536	      d_lazyCones[lambda];
537	  if (sub.negated < pairs.size())
538	  {
539	    for (size_t i = sub.negated; i < pairs.size(); i++)
540	    {
541	      Node disjunct = pairs[i].first;
542	      if (!sub.from.empty())
543	      {
544	        disjunct = disjunct.substitute(
545	            sub.from.begin(), sub.from.end(), sub.to.begin(), sub.to.end());
546	      }
547	      sub.covered = sub.covered.isNull()
548	                        ? disjunct
549	                        : d_nm->mkNode(Kind::OR, sub.covered, disjunct);
550	    }
551	    sub.negated = pairs.size();
552	    if (sub.pushed)
553	    {
554	      sub.engine->pop();
555	    }
556	    sub.engine->push();
557	    sub.engine->assertFormula(sub.covered.notNode());
558	    sub.pushed = true;
559	  }
560	
561	  lazyHilbert(literal, sub);
562	}
